    from collections import Counter
    bg = Counter(c for row in grid for c in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    blobs = []
    used = set()
    for r in range(H - 1):
        for c in range(W - 1):
            cells = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            cols = {grid[a][b] for a, b in cells}
            if len(cols) >= 3 and bg not in cols and not any(cell in used for cell in cells):
                blobs.append((set(cells), (r + 0.5, c + 0.5)))
